import SwiftUI

@available(iOS 27.0, *)
struct SearchTabsView: View {
    enum TabID: Hashable { case learn, favorites, search }
    @State private var selection: TabID = .learn
    @State private var query = ""

    var body: some View {
        TabView(selection: $selection) {
            Tab("Lernen", systemImage: "book", value: .learn) {
                LearningView()
            }
            Tab("Favoriten", systemImage: "heart", value: .favorites) {
                FavoritesView()
            }
            Tab(value: .search, role: .search) {
                SearchResultsView(query: query)
                    .searchable(text: $query, prompt: "Themen suchen")
            }
        }
    }
}

import SwiftUI

@available(iOS 27.0, *)
struct MinimizingTabsView: View {
    @State private var minimizesTabs = true

    var body: some View {
        TabView {
            Tab("Feed", systemImage: "rectangle.stack") {
                NavigationStack {
                    List(1...100, id: \.self) { Text("Lektion \($0)") }
