import SwiftUI

struct AnimatedBindingView: View {
    @State private var expanded = false

    var body: some View {
        VStack(spacing: 24) {
            RoundedRectangle(cornerRadius: expanded ? 32 : 12)
                .fill(.blue.gradient)
                .frame(height: expanded ? 260 : 100)

            Toggle("Erweitert", isOn: $expanded.animation(.spring(duration: 0.45)))
        }
        .padding()
    }
}

import SwiftUI

struct FavoriteSymbolView: View {
    @State private var isFavorite = false
    @State private var bounceTrigger = 0

    var body: some View {
        Button {
            isFavorite.toggle()
            bounceTrigger += 1
        } label: {
            Image(systemName: isFavorite ? "heart.fill" : "heart")
                .font(.system(size: 52))
                .foregroundStyle(isFavorite ? .pink : .secondary)
                .contentTransition(.symbolEffect(.replace))
                .symbolEffect(.bounce, value: bounceTrigger)
        }
    }
}

import SwiftUI

struct GradientGallery: View {
    var body: some View {
        ScrollView {
            VStack(spacing: 16) {
                card(LinearGradient(colors: [.indigo, .cyan], startPoint: .topLeading, endPoint: .bottomTrailing), title: "Linear")
                card(RadialGradient(colors: [.yellow, .orange, .pink], center: .center, startRadius: 8, endRadius: 180), title: "Radial")
                card(AngularGradient(colors: [.purple, .blue, .mint, .purple], center: .center), title: "Angular")
                card(MeshGradient(width: 2, height: 2, points: [[0, 0], [1, 0], [0, 1], [1, 1]], colors: [.indigo, .cyan, .purple, .mint]), title: "Mesh")
            }
            .padding()
        }
    }

    private func card<S: ShapeStyle>(_ style: S, title: String) -> some View {
        Text(title).font(.title.bold()).foregroundStyle(.white)
            .frame(maxWidth: .infinity, minHeight: 160)
            .background(style, in: .rect(cornerRadius: 24))
    }
}
